WITH base AS (SELECT id, product_name, category, brand, price, cost, stock_qty, tags, supplier_id, FLOOR(price) AS price_whole, COALESCE(brand, 'N/A') AS brand_filled FROM products WHERE launch_date >= DATE '2023-12-23' AND brand IS NOT NULL AND ARRAY_CONTAINS(tags, 'premium')) SELECT CASE WHEN price >= 970 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, CORR(price, cost) AS corr_price_cost, ROUND(AVG(price_whole), 2) AS avg_price_whole, SUM(price) AS total_price, ROUND(AVG(cost), 2) AS avg_cost, CORR(stock_qty, price) AS corr_stock_qty_price, SIZE(COLLECT_SET(category)) AS num_categories FROM base GROUP BY price_tier HAVING CORR(price, cost) >= 0 ORDER BY corr_stock_qty_price DESC NULLS FIRST;
